from dataclasses import dataclass, replace
from enum import Enum, auto


class DomainError(Exception):
    """Base class for errors the caller may handle as business failures."""


class UnknownStatusError(DomainError):
    pass


class InvalidTransitionError(DomainError):
    pass


class EnrollmentStatus(Enum):
    ACTIVE = auto()
    SUSPENDED = auto()
    GRADUATED = auto()


@dataclass(frozen=True)
class StudentProfile:
    student_id: str
    status: EnrollmentStatus = EnrollmentStatus.ACTIVE

    def __post_init__(self) -> None:
        if not isinstance(self.student_id, str):
            raise TypeError("student_id must be str")
        object.__setattr__(self, "student_id", self.student_id.strip())
        if not self.student_id:
            raise ValueError("student_id cannot be blank")
        if not isinstance(self.status, EnrollmentStatus):
            raise TypeError("status must be EnrollmentStatus")


ALLOWED = {
    EnrollmentStatus.ACTIVE: {EnrollmentStatus.SUSPENDED, EnrollmentStatus.GRADUATED},
    EnrollmentStatus.SUSPENDED: {EnrollmentStatus.ACTIVE, EnrollmentStatus.GRADUATED},
    EnrollmentStatus.GRADUATED: set(),
}


def parse_status(text: str) -> EnrollmentStatus:
    if not isinstance(text, str):
        raise TypeError("status text must be str")
    try:
        return EnrollmentStatus[text.strip().upper()]
    except KeyError as error:
        raise UnknownStatusError(f"unknown status: {text!r}") from error


def move_to(profile: StudentProfile, target: EnrollmentStatus) -> StudentProfile:
    if not isinstance(profile, StudentProfile):
        raise TypeError("profile must be StudentProfile")
    if not isinstance(target, EnrollmentStatus):
        raise TypeError("target must be EnrollmentStatus")
    if target is profile.status:
        return profile
    if target not in ALLOWED[profile.status]:
        raise InvalidTransitionError(
            f"cannot move from {profile.status.name} to {target.name}"
        )
    return replace(profile, status=target)


def expect(error_type: type[BaseException], action) -> BaseException:
    try:
        action()
    except error_type as error:
        return error
    raise AssertionError(f"expected {error_type.__name__}")


def run_checks() -> None:
    original = StudentProfile(" S01 ")
    assert original.student_id == "S01"
    assert parse_status(" suspended ") is EnrollmentStatus.SUSPENDED
    suspended = move_to(original, EnrollmentStatus.SUSPENDED)
    graduated = move_to(suspended, EnrollmentStatus.GRADUATED)
    assert original.status is EnrollmentStatus.ACTIVE
    assert graduated.status is EnrollmentStatus.GRADUATED
    assert move_to(graduated, EnrollmentStatus.GRADUATED) is graduated

    unknown = expect(UnknownStatusError, lambda: parse_status("paused"))
    assert isinstance(unknown.__cause__, KeyError)
    expect(InvalidTransitionError, lambda: move_to(graduated, EnrollmentStatus.ACTIVE))
    expect(TypeError, lambda: parse_status(None))
    expect(TypeError, lambda: move_to(original, "SUSPENDED"))
    expect(ValueError, lambda: StudentProfile("   "))


if __name__ == "__main__":
    run_checks()
    print("domain-errors checks: OK")
